+        let n_rows = l1.shape().elem_count() / size_sorted_axis;
+
+        // Replicate the kernel’s internal block sizing to derive `n_blocks`
+        let tn = 4usize;
+        let mut bn = match (size_sorted_axis + tn - 1) / tn {
+            v if v > 256 => 512,
+            v if v > 128 => 256,
+            v if v > 64 => 128,
+            v if v > 32 => 64,
+            _ => 32,
+        };
+        if bn == 512 && s1.dtype().size_in_bytes() > 4 {
