+    ];
+
+    foreach ($prefixes as $prefix => $baseDir) {
+        if (strncmp($class, $prefix, strlen($prefix)) === 0) {
+            $relative = substr($class, strlen($prefix));
+            $file = $baseDir . str_replace('\\', '/', $relative) . '.php';
+            if (file_exists($file)) {
+                require $file;
+            }
+        }
+    }
+});

