+    $prefixes = [
+        'OCA\\Analytics\\' => __DIR__ . '/../lib/',
+        'OCA\\Analytics\\Tests\\' => __DIR__ . '/',
+        'OCP\\' => __DIR__ . '/Stubs/OCP/',
