+export const extractOptionsWithAgent = z
+  .object({
+    mode: z.enum(["llm"]).default("llm"),
+    schema: z.any().optional(),
+    prompt: z.string().max(10000).optional(),
+    temperature: z.number().optional(),
+    agent: z
